#!/usr/bin/env bash
# Builds the MyTube demo seed (claude). Every clip is generated by ffmpeg, so there
# is no real footage, personal data or third-party media. Output: $1 (default ./seed)
#   seed/db.json, seed/uploads/*.mp4, seed/uploads/thumbnails/*.png
set -euo pipefail
OUT=${1:-./seed}
rm -rf "$OUT"; mkdir -p "$OUT/uploads/thumbnails"

# id|file|title|category|tags(comma)|lavfi source
CLIPS=(
  "6b1f0c2e-0001-4a00-9000-000000000001|mandelbrot-zoom.mp4|Mandelbrot zoom|Generative|fractal,maths|mandelbrot=s=640x360:rate=25"
  "6b1f0c2e-0002-4a00-9000-000000000002|game-of-life.mp4|Game of Life|Generative|simulation,cells|life=s=640x360:mold=10:rate=25:ratio=0.1:death_color=#1b2a4a:life_color=#7fd1ff,scale=640:360:flags=neighbor"
  "6b1f0c2e-0003-4a00-9000-000000000003|colour-test-card.mp4|Colour test card|Test patterns|calibration,colour|testsrc2=s=640x360:rate=25"
  "6b1f0c2e-0004-4a00-9000-000000000004|smpte-bars.mp4|SMPTE bars|Test patterns|calibration,broadcast|smptehdbars=s=640x360:rate=25"
  "6b1f0c2e-0005-4a00-9000-000000000005|gradient-drift.mp4|Gradient drift|Ambient|calm,colour|gradients=s=640x360:rate=25:speed=0.02:n=4"
  "6b1f0c2e-0006-4a00-9000-000000000006|cellular-automaton.mp4|Cellular automaton|Generative|simulation,rule110|cellauto=s=640x360:rule=110:rate=25,format=yuv420p"
)
SECS=12
DB_VIDEOS=""; i=0
for row in "${CLIPS[@]}"; do
  IFS='|' read -r id file title cat tags src <<<"$row"
  ffmpeg -nostdin -loglevel error -y -f lavfi -i "$src" \
    -f lavfi -i "sine=frequency=$((220 + i*55)):sample_rate=44100" \
    -t "$SECS" -vf "format=yuv420p" -c:v libx264 -preset veryfast -crf 28 -c:a aac -b:a 64k \
    -movflags +faststart -shortest "$OUT/uploads/$file"
  ffmpeg -nostdin -loglevel error -y -ss 3 -i "$OUT/uploads/$file" -frames:v 1 -s 320x180 \
    "$OUT/uploads/thumbnails/thumb-$id.png"
  tagjson=$(printf '%s' "$tags" | awk -F, '{for(j=1;j<=NF;j++) printf "%s\"%s\"", (j>1?",":""), $j}')
  created=$(date -u -d "2026-10-0$((i+1))T1$i:00:00Z" +%Y-%m-%dT%H:%M:%S.000Z)
  DB_VIDEOS+="${DB_VIDEOS:+,}{\"id\":\"$id\",\"title\":\"$title\",\"filename\":\"$file\",\"path\":\"/uploads/$file\",\"thumbnail\":\"/uploads/thumbnails/thumb-$id.png\",\"category\":\"$cat\",\"tags\":[$tagjson],\"uploadedBy\":\"demo\",\"createdAt\":\"$created\"}"
  i=$((i+1))
done

cat >"$OUT/db.json" <<JSON
{
  "videos": [$DB_VIDEOS],
  "categories": ["Generative", "Test patterns", "Ambient"],
  "tags": ["fractal","maths","simulation","cells","calibration","colour","broadcast","calm","rule110"],
  "users": [{"id":"00000000-demo-4000-8000-000000000001","email":"demo@mytube.demo","username":"demo","name":"Demo viewer","role":"user","createdAt":"2026-10-01T00:00:00.000Z"}],
  "settings": {"enableDevMock": false}
}
JSON
node -e 'JSON.parse(require("fs").readFileSync(process.argv[1]))' "$OUT/db.json"
du -sh "$OUT"; ls "$OUT/uploads" "$OUT/uploads/thumbnails"
